package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamGovernanceBank2 {
  private const val T = "යහපාලනය, නීතියේ ආධිපත්‍යය, RTI හා ගැටුම් නිරාකරණය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ගැටුමක් විසඳීමේදී පාර්ශ්ව දෙක අතර සන්නිවේදනය සම්පූර්ණයෙන් බිඳ වැටුණු විට සාමාන්‍යයෙන් ගන්නා පළමු පියවර කුමක්ද?", "මධ්‍යස්ථ පාර්ශ්වයක මැදිහත්වීමෙන් සංවාද නාලිකා යළි විවෘත කිරීම", "එක් පාර්ශ්වයක් සිරගත කිරීම", "විරෝධතා පුවරු ප්‍රදර්ශනය කිරීම", "නීතිමය ලේඛන විනාශ කිරීම", "සන්නිවේදනය යළි ගොඩනැගීම සඳහා සුදුසු මධ්‍යස්ථ පුද්ගලයෙකු හරහා සාකච්ඡාවට පරිසරය සැකසීම අත්‍යවශ්‍යය."),
    q("සාමකාමී ගැටුම් නිරාකරණයේදී 'පහසුකම් සපයන්නා' (Facilitator) ඉටු කරන කාර්යභාරය කුමක්ද?", "සාකච්ඡාව සුමටව පවත්වාගෙන යාමට මග පෙන්වීම මිස තීරණ නොදීම", "පාර්ශ්ව දෙකටම දඩ පැනවීම", "බලහත්කාරයෙන් ගිවිසුමක් ලිවීම", "නඩු තීන්දු ප්‍රකාශ කිරීම", "සාකච්ඡා සභාවේ විනය, සමාන අවස්ථා හා අවධානය රැකදීම පහසුකම් සපයන්නාගේ කාර්යයයි."),
    q("ආරවුලක් විසඳීමේදී දෙපාර්ශ්වයම තම ඉල්ලීම්වලට පමණක් නොඇලී 'මූලික අවශ්‍යතා' (Interests) හඳුනාගැනීම වැදගත් වන්නේ ඇයි?", "පොදු එකඟතාවයකට එළඹිය හැකි නිර්මාණාත්මක විකල්ප සොයා ගැනීමට", "අනෙක් පාර්ශ්වය පරාජය කිරීමට", "නඩුව වසර ගණනාවක් ඇදගෙන යාමට", "විශාල දඩ මුදලක් අය කිරීමට", "බාහිර ස්ථාවරයන්ට (Positions) වඩා යටින් ඇති සැබෑ අවශ්‍යතා තේරුම් ගත් විට Win-Win විසඳුම් පහසු වේ."),
    q("පවුලේ හෝ ප්‍රජාවේ ගැටුමක් උත්සන්න වීමට ප්‍රධාන වශයෙන් බලපාන මානසික හා සමාජීය හේතුවක් කුමක්ද?", "වැරදි වැටහීම්, අන් අයට ඇහුම්කන් නොදීම හා පූර්ව විනිශ්චයන්", "නිතිපතා විවෘතව කතාබහ කිරීම", "සමානව සම්පත් බෙදාගැනීම", "සමථ මණ්ඩලයේ සහාය ගැනීම", "සන්නිවේදන දුර්වලතා හා අන් අයගේ දෘෂ්ටිකෝණය නොසලකා හැරීම ගැටුම් උග්‍ර කරයි."),
    q("ශ්‍රී ලංකාවේ 1988 සමථ මණ්ඩල පනත යටතේ 'විශේෂ සමථ මණ්ඩල' පිහිටුවා ඇත්තේ කුමන ආකාරයේ ගැටුම් විසඳීමටද?", "ඉඩම් ආරවුල්, වාණිජ ආරවුල් සහ සුළු ප්‍රජා ආරවුල්", "ජාත්‍යන්තර යුද අපරාධ නඩු", "ව්‍යවස්ථා සංශෝධන පනත්", "මැතිවරණ පෙත්සම්", "සාමාන්‍ය සමථ මණ්ඩලවලට අමතරව විශේෂිත ඉඩම් හා මූල්‍ය ආරවුල් විසඳීමට විශේෂ සමථ මණ්ඩල ක්‍රියා කරයි."),
    q("ගැටුමකදී 'තීරණ ගැනීමේ බලය පාර්ශ්වකරුවන් සතුවම පවතින' විකල්ප ආරවුල් විසඳීමේ ක්‍රම දෙක කවරේද?", "සාකච්ඡාව (Negotiation) සහ සමථකරණය (Mediation)", "නඩු පැවරීම සහ බේරුම්කරණය", "පොලිස් දඬුවම් සහ හමුදා නීතිය", "රීට් ආඥා සහ දෝෂාභියෝග", "සාකච්ඡාවේදී හා සමථකරණයේදී කිසිදු බාහිර අයෙකු තීන්දුවක් බලෙන් නොපනවන අතර පාර්ශ්ව දෙකම තීරණ ගනී."),
    q("ප්‍රචණ්ඩ ගැටුමක් අවසන් වූ පසු සමාජය තුළ යළි විශ්වාසය හා සමගිය ගොඩනැගීමේ දිගුකාලීන ක්‍රියාවලිය කුමක්ද?", "සාමය ගොඩනැගීම හා සංහිඳියාව (Peacebuilding & Reconciliation)", "ආර්ථික සම්බාධක පැනවීම", "හදිසි නීතිය දීර්ඝ කිරීම", "ජනමාධ්‍ය වාරණය කිරීම", "අතීත තුවාල සුවපත් කර යුක්තිය, සංවාදය හා සමානාත්මතාව මත ස්ථාවර සාමයක් ගොඩනැගීම මෙයයි."),
    q("යුද්ධයකින් හෝ ප්‍රචණ්ඩත්වයකින් පසු සත්‍ය සෙවීම, වන්දි ගෙවීම හා යුක්තිය ඉටු කිරීම හඳුන්වන්නේ කුමන නමින්ද?", "සංක්‍රාන්ති යුක්තිය (Transitional Justice)", "පරිපාලන මධ්‍යගතකරණය", "බහු මන්ත්‍රී නියෝජනය", "රාජ්‍ය විගණනය", "ගැටුම් පැවති සමාජයක වින්දිතයන්ට සාධාරණය ඉටු කර යළි ගැටුම් ඇති නොවීමට ගන්නා පියවර මෙයයි."),
    q("ගැටුම් කළමනාකරණයේදී 'කරුණු සාධාරණව ඉදිරිපත් කරන I-Statements (මට දැනෙන ආකාරය)' භාවිතය ප්‍රයෝජනවත් වන්නේ ඇයි?", "අනෙකාට චෝදනා නොකර තම ගැටලුව හා හැඟීම පැහැදිලි කර සංවාදය පහසු කරන බැවිනි", "අනෙකා බියගන්වා නිහඬ කිරීමට", "නීතිඥ ගාස්තු අඩු කිරීමට", "අධිකරණ නඩුවක් කඩිනම් කිරීමට", "'ඔබ සැමවිටම වැරදියි' යනුවෙන් චෝදනා කිරීම වෙනුවට තමාට බලපෑ ආකාරය කීමෙන් ආරක්ෂක කෝපය අඩුවේ."),
    q("රාජ්‍ය ආයතන තුළ 'සංසන්දනාත්මක විනිවිදභාවය' සඳහා 2016 අංක 12 RTI පනතේ 'පොදු අධිකාරියක්' යන්නට අයත් නොවන්නේ කුමක්ද?", "කිසිදු රාජ්‍ය අරමුදලක් හෝ රාජ්‍ය බලයක් නොලබන පෞද්ගලික පවුල් භාරයක්", "අමාත්‍යාංශ සහ දෙපාර්තමේන්තු", "පළාත් සභා සහ ප්‍රාදේශීය සභා", "රාජ්‍ය විශ්වවිද්‍යාල සහ රාජ්‍ය බැංකු", "රජයේ මුදල්, ව්‍යවස්ථාපිත බලය හෝ පොදු සේවා නොමැති සම්පූර්ණයෙන් පෞද්ගලික කටයුතු RTI පනතට අයත් නොවේ."),
    q("තොරතුරු දැනගැනීමේ පනත යටතේ පුරවැසියෙකුට රජයේ ආයතනයකින් තොරතුරක් ලබාගත හැකි ආකාරයක් නොවන්නේ කුමක්ද?", "නිලධාරියාගේ නිවසට ගොස් බලෙන් ලිපිගොනු රැගෙන යාම", "ලිපි ලේඛන පරීක්ෂා කිරීම හා සටහන් තබාගැනීම", "සහතික කළ ඡායා පිටපත් ලබාගැනීම", "ඉලෙක්ට්‍රොනික මාධ්‍යයෙන් හෝ විද්‍යුත් තැපෑලෙන් ලබාගැනීම", "RTI පනත අනුව විධිමත්ව ලියවිලි පරීක්ෂාව, පිටපත් හෝ ඩිජිටල් ගොනු ඉල්ලා සිටිය හැක."),
    q("2016 අංක 12 දරන RTI පනත අනුව පනතේ විධිවිධාන ක්‍රියාත්මක කිරීමට පෙර රාජ්‍ය රහස් පනත (Official Secrets Act) සමඟ ගැටුමක් ඇති වුවහොත් කුමක් වලංගු වේද?", "තොරතුරු දැනගැනීමේ අයිතිවාසිකම පිළිබඳ පනතේ විධිවිධාන ප්‍රමුඛ වේ", "පැරණි යටත්විජිත නීතිය සැමවිටම ප්‍රමුඛ වේ", "පොලිස්පතිවරයාගේ තීරණය අවසන් වේ", "විෂය භාර අමාත්‍යවරයා තීරණය කරයි", "RTI පනතේ 4 වන වගන්තිය අනුව තොරතුරු දීම සීමා කරන පැරණි නීතිවලට වඩා RTI පනත බලවත් වේ."),
    q("RTI පනත යටතේ 'රාජ්‍ය පෞද්ගලිකත්වය' (Section 5(1)(a)) රැකීමට තොරතුරක් ප්‍රතික්ෂේප කළ හැක්කේ කවදාද?", "මහජන සුබසිද්ධියට කිසිදු සම්බන්ධයක් නැති අයෙකුගේ අතිශය පෞද්ගලික තොරතුරු ඉල්ලූ විට", "ඇමතිවරුන්ගේ විදෙස් සංචාර වියදම් ඉල්ලූ විට", "පාසල් ගොඩනැගිලි ටෙන්ඩර් ඉල්ලූ විට", "පළාත් සභා අයවැය විස්තර ඉල්ලූ විට", "පොදු කටයුත්තකට අදාළ නොවන පුද්ගලික ජීවිතයට අනිසි බලපෑම් කරන තොරතුරු සීමා කළ හැක."),
    q("විභාග දෙපාර්තමේන්තුව විසින් පැවැත්වීමට නියමිත අ.පො.ස. සාමාන්‍ය පෙළ ප්‍රශ්න පත්‍රයක පිටපතක් මැතිවරණයට පෙර RTI මඟින් ඉල්ලා සිටියහොත් කුමක් සිදුවේද?", "5(1)(ඤ) වගන්තිය අනුව විභාග රහස්‍යභාවය මත ඉල්ලීම නීත්‍යානුකූලව ප්‍රතික්ෂේප කෙරේ", "වහාම පිටපත ලබා දිය යුතුය", "පැය 48ක් ඇතුළත ප්‍රසිද්ධ කළ යුතුය", "දින 14කින් අන්තර්ජාලයේ දැමිය යුතුය", "විභාග ප්‍රශ්න පත්‍ර හා ඇගයීම්වල විශ්වසනීයත්වය හා රහස්‍යභාවය ආරක්ෂා කිරීම RTI ව්‍යතිරේකයකි."),
    q("කිසියම් අයෙකුගේ තොරතුරු ඉල්ලීමක් සංකීර්ණ බැවින් දින 14කින් දීමට අපහසු නම් තොරතුරු නිලධාරියාට උපරිම වශයෙන් ගත හැකි අතිරේක කාලය කීයද?", "තවත් දින 21ක් දක්වා (හේතු ලිඛිතව දන්වා)", "තවත් වසර 2ක් දක්වා", "තවත් මාස 6ක් දක්වා", "සීමාවක් නොමැත", "විශාල තොරතුරු ප්‍රමාණයක් රැස් කිරීමට අවශ්‍ය විට හේතු දන්වා දින 21කට නොවැඩි කාලයකින් දීර්ඝ කළ හැක."),
    q("ශ්‍රී ලංකාවේ තොරතුරු දැනගැනීමේ අයිතිවාසිකම පිළිබඳ කොමිෂන් සභාවේ සාමාජිකයන් ගණන කීයද?", "සාමාජිකයන් 5", "සාමාජිකයන් 3", "සාමාජිකයන් 15", "සාමාජිකයන් 2", "නීතිඥ සංගමය, මාධ්‍ය හා සිවිල් සංවිධාන නියෝජනය වන සාමාජිකයන් 5 දෙනෙකුගෙන් RTI කොමිසම සමන්විතය."),
    q("රටේ නීතියේ ආධිපත්‍යය තහවුරු කිරීම සඳහා 'නීති මහජනතාවට පැහැදිලි හා ප්‍රවේශ විය හැකි වීම' අත්‍යවශ්‍ය වන්නේ ඇයි?", "පුරවැසියන්ට තමන්ට අවසර ඇති හා තහනම් දේ කුමක්දැයි කලින් දැනගත හැකි වීමට", "රජයේ ගැසට් මුද්‍රණාලයට ලාභ ලැබීමට", "නීතිඥයන් සංඛ්‍යාව අඩු කිරීමට", "අධිකරණ වසා දැමීමට", "රහසිගත හෝ අපැහැදිලි නීති මඟින් පුරවැසියන්ට දඬුවම් දීම නීතියේ ආධිපත්‍යයට සම්පූර්ණයෙන් පටහැනිය."),
    q("ඒ.වී. ඩයිසිගේ නීතියේ ආධිපත්‍යය සංකල්පයේ 'දෙවන මූලධර්මය' වන 'නීතිය ඉදිරියේ සමානාත්මතාව' මඟින් කියැවෙන්නේ කුමක්ද?", "සියලු තරාතිරම්වල පුරවැසියන් එකම සාමාන්‍ය අධිකරණ පද්ධතියට හා නීතියට යටත් වීම", "ඇමතිවරුන්ට වෙනම රහස් නීති පැවතීම", "සාමාන්‍ය ජනතාවට නීතිඥයන් තහනම් වීම", "ධනවතුන්ට දඩ පමණක් ගැසීම", "රාජ්‍ය නිලධාරීන් වුවද නීතිය කඩ කළ විට සාමාන්‍ය නීතිය ඉදිරියේ වගකිව යුතුය."),
    q("යහපාලනයේදී 'නිලධාරිවාදී ප්‍රමාදය' (Red Tape) අවම කර ගැනීමට රජයේ ආයතනයකට ගත හැකි ප්‍රායෝගික පියවරක් කුමක්ද?", "අනවශ්‍ය අත්සන් හා පෝරම සරල කර එක් කවුළුවකින් සේවා (One-Stop Service) සැලසීම", "සෑම අයදුම්පතක්ම අමාත්‍යවරයා වෙත යැවීම", "කාර්යාල විවෘත කරන දින අඩු කිරීම", "මහජන පැමිණිලි පෙට්ටිය ඉවත් කිරීම", "සරල හා කඩිනම් ක්‍රියාපටිපාටි මඟින් පුරවැසියන්ට පහසුවෙන් හා අල්ලස් රහිතව සේවා ලැබේ."),
    q("රාජ්‍ය අංශයේ නිලධාරියෙකු අනුගමනය කළ යුතු 'සේවා ආචාරධර්ම' (Code of Ethics) තුළ ප්‍රමුඛ වන්නේ කුමක්ද?", "අවංකභාවය, අපක්ෂපාතීත්වය, රහස්‍යභාවය හා මහජන හිතෛෂීභාවය", "පෞද්ගලික ව්‍යාපාරවලට ප්‍රමුඛතාව දීම", "දේශපාලන පක්ෂ රැස්වීම්වලට යාම", "සේවා ලාභීන්ගෙන් තෑගි ඉල්ලා සිටීම", "රාජ්‍ය සේවයේ ගෞරවය හා ජනතා විශ්වාසය රැකෙන්නේ උසස් වෘත්තීය ආචාරධර්ම පිළිපැදීමෙනි."),
    q("රජයේ භාණ්ඩාගාර මුදල් අවභාවිතයක් සිදු වූ විට ඒ පිළිබඳව පාර්ලිමේන්තුවේ COPE හා COPA කාරක සභාවලට මඟ පෙන්වන විශේෂඥයා කවුද?", "විගණකාධිපතිවරයා", "මැතිවරණ කොමසාරිස් ජනරාල්වරයා", "පළාත් ආණ්ඩුකාරවරයා", "සමථ මණ්ඩල සභාපතිවරයා", "රාජ්‍ය ආයතනවල මූල්‍ය වාර්තා පරීක්ෂා කර දුර්වලතා පෙන්වා දීමට විගණකාධිපති දෙපාර්තමේන්තුව කමිටුවලට සහාය වේ."),
    q("2018 අංක 19 දරන ජාතික විගණන පනත යටතේ හඳුන්වා දුන් 'අධිභාරය' (Surcharge) යනු කුමක්ද?", "රාජ්‍ය මුදල් අවභාවිතයකින් හෝ නොසැලකිල්ලෙන් සිදු කළ අලාභය වගකිවයුතු නිලධාරියාගෙන් ආපසු අයකර ගැනීම", "පුරවැසියන්ගෙන් අලුත් වරිපනම් බද්දක් ගැනීම", "විදේශිකයන්ට පනවන වීසා ගාස්තුව", "ව්‍යාපාරිකයන්ට දෙන බදු සහනය", "මූල්‍ය අලාභ සිදු කරන වගකිවයුත්තන්ගෙන් එම මුදල පෞද්ගලිකව අයකර ගැනීමට විගණන පනතෙන් ඉඩ සැලසීය."),
    q("යහපාලනය ක්‍රියාත්මක වන රටක ආර්ථිකයට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "දේශීය හා විදේශීය ආයෝජක විශ්වාසය වැඩි වී තිරසාර ආර්ථික වර්ධනයක් ඇති වීම", "රජයේ සියලු කර්මාන්තශාලා වැසී යාම", "බදු ආදායම් සම්පූර්ණයෙන් නතර වීම", "උද්ධමනය සීඝ්‍රයෙන් ඉහළ යාම", "නීතියේ ස්ථාවරත්වය හා දූෂණ අවම වීම ආයෝජන ආකර්ෂණය කර ගැනීමට ප්‍රබල සාධකයකි."),
    q("දූෂණය හා වංචාව පිටුදැකීම සඳහා පුරවැසියන් තුළ 'ශුන්‍ය ඉවසීම' (Zero Tolerance) ඇති කිරීම යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "සුළු හෝ විශාල ඕනෑම අල්ලස් හා දූෂණ ක්‍රියාවකට කිසිසේත් ඉඩ නොදීමේ ආකල්පය", "සුළු අල්ලස් නොසලකා හැරීම", "දූෂිත නිලධාරීන් ආරක්ෂා කිරීම", "නීතිය සම්පූර්ණයෙන් ඉවත් කිරීම", "රථවාහන දඩයකින් බේරීමට දෙන සුළු මුදලේ සිට මහා පරිමාණ දූෂණ දක්වා සියල්ල ප්‍රතික්ෂේප කළ යුතුය."),
    q("ශ්‍රී ලංකාවේ 2023 අංක 9 දරන දූෂණ විරෝධී පනත යටතේ 'ලිංගික අල්ලස්' හෝ වෙනත් අද්‍රව්‍යමය වාසි ලබාගැනීම සලකන්නේ කෙසේද?", "දඬුවම් ලැබිය හැකි බරපතළ දූෂණ වරදක් ලෙස", "සුළු පරිපාලන ගැටලුවක් ලෙස", "නීත්‍යානුකූල ක්‍රියාවක් ලෙස", "විනය කමිටු තීරණයක් ලෙස පමණක්", "මුදල් පමණක් නොව ඕනෑම අයුතු වාසියක් හෝ ලිංගික අල්ලසක් ඉල්ලීම නව පනතින් බරපතළ අපරාධයකි."),
    q("ගැටුම් නිරාකරණයේදී 'පහළට ඇද දැමීම' (De-escalation) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "උණුසුම් වී ඇති ආරවුලක ආතතිය හා කෝපය ක්‍රමයෙන් සමනය කර සාකච්ඡාවට ගෙන ඒම", "ප්‍රචණ්ඩත්වය තවත් වැඩි කිරීම", "අවි ආයුධ බෙදාදීම", "විරුද්ධ පාර්ශ්වය පිටුවහල් කිරීම", "ගෞරවනීය වචන හා සන්සුන් සවන්දීම මඟින් ගැටුම ප්‍රචණ්ඩ අතට හැරීම වැළැක්විය හැක."),
    q("පුද්ගලයෙකු ගැටුමකට මුහුණ දෙන ආකාර පහ අතුරින් 'කැස්බෑවා' හෝ 'මඟහැරීම' (Avoiding) සංකේතවත් කරන්නේ කුමක්ද?", "ප්‍රශ්නයට මුහුණ නොදී පසුබැස සිටීමෙන් ගැටලුව නොවිසඳී පැවතීම", "සහයෝගීතාවෙන් Win-Win විසඳුමක් සෙවීම", "බලහත්කාරයෙන් අනෙකා යටපත් කිරීම", "මධ්‍යස්ථ සමථකරුවෙකු වීම", "සමහර අවස්ථාවල ආරවුල මඟහැර සිටීම නිසා පාර්ශ්ව දෙකේම අවශ්‍යතා ඉටු නොවේ."),
    q("ගැටුම් නිරාකරණ විලාසයන්හිදී 'බලහත්කාරී තරගය' (Competing / Forcing) මඟින් සිදුවන ප්‍රධාන හානිය කුමක්ද?", "එක් අයෙකුගේ කැමැත්ත පමණක් ඉටු වී දෙදෙනා අතර මිත්‍රත්වය හා විශ්වාසය බිඳ වැටීම", "දෙදෙනාටම උපරිම සතුට ලැබීම", "විසඳුම ස්ථිර සාමයක් වීම", "සියලු ප්‍රශ්න එකවර නිම වීම", "මම දිනා අනෙකා පැරදවීමට යාමෙන් දිගුකාලීන සහයෝගීතාව විනාශ වේ."),
    q("ගැටුමක් සඳහා සාකච්ඡා කිරීමට යාමේදී 'BATNA' (Best Alternative to a Negotiated Agreement) දැන සිටීම වැදගත් වන්නේ ඇයි?", "එකඟතාවක් නොලැබුණහොත් තමාට ඇති හොඳම විකල්පය කුමක්දැයි දැන අසාධාරණ කොන්දේසිවලින් මිදීමට", "සාකච්ඡාව ආරම්භයේදීම කඩාකප්පල් කිරීමට", "අනෙක් පාර්ශ්වයට බොරු පොරොන්දු දීමට", "අධිකරණ ගාස්තු දෙගුණ කිරීමට", "සාකච්ඡාවේ තමාගේ සාධාරණ සීමාව හඳුනාගෙන වඩා හොඳ තීරණයක් ගැනීමට BATNA උපකාරී වේ."),
    q("සාමකාමී ගැටුම් නිරාකරණයට බාධා කරන ප්‍රධානතම මානසික බාධකයක් වන 'ඒකාකෘති' (Stereotypes) යනු මොනවාද?", "යම් ජාතියක්, ආගමක් හෝ කණ්ඩායමක් ගැන පදනම් විරහිතව සාමාන්‍යකරණය කළ වැරදි මතයන්", "සත්‍ය විද්‍යාත්මක සාක්ෂි", "අධිකරණ නඩු තීන්දු වාර්තා", "පළාත් පාලන අතුරු ව්‍යවස්ථා", "සෑම පුද්ගලයෙකුම පොදු ලේබලයකින් මැන බැලීම අගතීන්ට හා සමාජ ගැටුම්වලට මග පාදයි."),
    q("විවිධත්වයෙන් යුත් සමාජයක සාමකාමී සහජීවනය ගොඩනැගීම සඳහා අත්‍යවශ්‍ය වන සමාජීය කුසලතාව කුමක්ද?", "සංස්කෘතික සංවේදීතාව හා අන්‍යෝන්‍ය ගරුත්වය", "ආත්මාර්ථකාමීත්වය", "ඒකාධිකාරී බලය", "අන්තවාදී ප්‍රචාරණය", "අනෙක් ජන කොටස්වල සිරිත් විරිත්, භාෂාව හා විශ්වාස තේරුම් ගෙන ගරු කිරීම සංහිඳියාව ගෙන දේ."),
    q("රටේ සියලු පුරවැසියන්ට පොදුවේ බලපාන ජාතික ප්‍රශ්නයකදී විරුද්ධ දේශපාලන පක්ෂ පවා එකට හිඳ ගන්නා සම්මුතිගත ප්‍රවේශය පෙන්වන්නේ කුමක්ද?", "යහපාලනයේ සම්මුතිගත (Consensus-oriented) ලක්ෂණය", "ඒකපාක්ෂික ආඥාදායකත්වය", "රහස් ඡන්ද ක්‍රමය", "ද්විපුරවැසි නීතිය", "පටු පක්ෂ වාසි පසෙකලා ජාතික යහපත වෙනුවෙන් පොදු එකඟතාවකට ඒම ප්‍රජාතන්ත්‍රවාදී පරිණත බවයි."),
    q("ශ්‍රී ලංකාවේ 'පරිපාලන කටයුතු පිළිබඳ පාර්ලිමේන්තු කොමසාරිස්' (ඔම්බුඩ්ස්මන්) පත් කරනු ලබන්නේ කෙසේද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාවේ අනුමැතියෙන් ජනාධිපතිවරයා විසින්", "පළාත් පාලන කොමසාරිස් විසින්", "විපක්ෂ සංවිධායක විසින්", "මහ නගර සභා නගරාධිපති විසින්", "21 වන සංශෝධනය අනුව ඔම්බුඩ්ස්මන්වරයා ව්‍යවස්ථා සභාවේ නිර්දේශය මත පත් කෙරෙන ස්වාධීන නිලධාරියෙකි."),
    q("රාජ්‍ය ආයතනයකින් වැරදි ලෙස විශ්‍රාම වැටුප ප්‍රමාද කිරීමක් ගැන පුරවැසියෙකුට අධිකරණයට නොගොස් ඉක්මනින් සහනයක් පැතිය හැකි ආයතනය කුමක්ද?", "පරිපාලන කටයුතු පිළිබඳ පාර්ලිමේන්තු කොමසාරිස් (ඔම්බුඩ්ස්මන්)", "මහාධිකරණය", "රේගු දෙපාර්තමේන්තුව", "විදේශ සේවා කාර්යාංශය", "විශ්‍රාම වැටුප්, ඉඩම් හා රාජ්‍ය සේවා පරිපාලන ප්‍රමාද ගැන ඔම්බුඩ්ස්මන් කාර්යාලයට නොමිලේ පැමිණිලි කළ හැක."),
    q("යහපාලනය තුළ 'ලැබැඳියාවන් අතර ගැටුම' (Conflict of Interest) යනු කුමක්ද?", "රාජ්‍ය නිලධාරියෙකුගේ පෞද්ගලික ලාභය හා මහජන රාජකාරි වගකීම එකිනෙකට ගැටෙන තත්ත්වය", "රටවල් දෙකක් අතර දේශසීමා යුද්ධය", "පාසල් ක්‍රීඩා තරගයක ආරවුල", "රජයේ නිවාඩු දින සංශෝධනය", "තමාට හෝ තම පවුලට ආර්ථික වාසි ලැබෙන රාජ්‍ය තීරණවලින් නිලධාරීන් ඉවත් විය යුතුය."),
    q("නීතියේ ආධිපත්‍යය ක්‍රියාත්මක වන රටක විධායක නිලධාරියෙකුට 'අභිමතානුසාරී බලය' (Discretionary Power) ලැබුණු විට එය භාවිත කළ යුත්තේ කෙසේද?", "සාධාරණව, අපක්ෂපාතීව හා පනතේ අරමුණට අනුකූලව පමණි", "තමන් කැමති මිතුරන්ට පමණක් වාසි සැලසෙන සේ", "හේතු කිසිවක් නොදක්වා අත්තනෝමතිකව", "ව්‍යවස්ථාවට පටහැනිව", "නීතියෙන් දෙන අභිමත බලය පවා යුක්තිසහගත බවේ (Reasonableness) සීමාවන්ට යටත් බව අධිකරණ පිළිගනී."),
    q("ශ්‍රී ලංකාවේ 'තොරතුරු දැනගැනීමේ පනත' පුරවැසි සවිබල ගැන්වීමේ ප්‍රබල ආයුධයක් වන්නේ කෙසේද?", "රජය සතු නිවැරදි දත්ත මත පදනම්ව දූෂණ හෙළි කර වගවීම ඉල්ලා සිටීමට හැකි වීමෙන්", "රජයේ සියලු නිලධාරීන් ඉවත් කිරීමට හැකි වීමෙන්", "පනත් කෙටුම්පත් නතර කිරීමට හැකි වීමෙන්", "බදු නොගෙවා සිටීමට හැකි වීමෙන්", "තොරතුරු යනු බලය වන බැවින් විමසිලිමත් පුරවැසියන්ට RTI මඟින් යහපාලනය ඉල්ලා සිටිය හැක."),
    q("ප්‍රාදේශීය ප්‍රජාව තුළ පවතින ජල හිඟයකදී හෝ පොදු මාර්ගයක් භාවිත කිරීමේදී ඇතිවන ගැටුමක් විසඳීමට වඩාත්ම සුදුසු ප්‍රවේශය කුමක්ද?", "සියලු පවුල් එක්රැස් වී සාකච්ඡාවෙන් සාධාරණ බෙදාගැනීමේ කාලසටහනක් සෑදීම", "පොදු ළිඳ වසා දැමීම", "මාර්ගය කඩා දැමීම", "පොලිස් ස්ථාන ඉදිරිපිට කලහ කිරීම", "පොදු සම්පත් ආරවුල්වලදී ප්‍රජා සාකච්ඡාව හා සමථකරණය තිරසාර සහයෝගීතාවක් ඇති කරයි."),
    q("රාජ්‍ය ආයතනයක සේවාවක් ලබාගැනීමේදී පුරවැසියන්ට නිරන්තරයෙන්ම 'මාර්ගගත පද්ධති' (Online Portals) හඳුන්වා දීමෙන් අඩු වන්නේ කුමක්ද?", "කාලය නාස්ති වීම, ප්‍රවාහන වියදම් හා මුහුණට මුහුණ සිදුවන අල්ලස් ඉල්ලීම්", "අධ්‍යාපන ප්‍රමිතිය", "මැතිවරණ දිස්ත්‍රික්ක ගණන", "නීතිඥ සේවාව", "e-Governance ක්‍රියාත්මක වීමෙන් ජනතාවට වේගවත් හා විනිවිදභාවයෙන් යුත් සේවා හිමිවේ."),
    q("ශ්‍රී ලංකාවේ ස්වාධීන කොමිෂන් සභා පද්ධතිය පළමු වරට ව්‍යවස්ථාපිතව හඳුන්වා දුන්නේ 2001 වසරේ කුමන සංශෝධනයෙන්ද?", "17 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය", "13 වන සංශෝධනය", "15 වන සංශෝධනය", "18 වන සංශෝධනය", "පොලිස්, මැතිවරණ හා රාජ්‍ය සේවයේ දේශපාලනීකරණය නැවැත්වීමට 2001 දී 17 වන සංශෝධනය සම්මත කෙරිණි."),
    q("18 වන ව්‍යවස්ථා සංශෝධනයෙන් අහෝසි කළ ව්‍යවස්ථා සභාව හා ස්වාධීන කොමිෂන් සභා යළි ශක්තිමත් කළ 2015 සංශෝධනය කුමක්ද?", "19 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය", "14 වන සංශෝධනය", "16 වන සංශෝධනය", "20 වන සංශෝධනය", "2015 අප්‍රේල් 19 වන සංශෝධනයෙන් ව්‍යවස්ථා සභාව, ජනාධිපති වාර දෙකේ සීමාව හා RTI පිහිටුවනු ලැබීය."),
    q("ගැටුමක් නිරාකරණය කිරීමේදී 'විනිවිදභාවයෙන් යුත් කරුණු පැහැදිලි කිරීම' (Clarification) උපකාරී වන්නේ කෙසේද?", "වැරදි අනුමාන හා සැකයන් දුරු කර පාර්ශ්ව දෙකටම පොදු අවබෝධයක් ලබාදීමට", "අලුත් ආරවුල් නිර්මාණය කිරීමට", "සාකච්ඡාව අවසන් කිරීමට", "නීතිය සැඟවීමට", "බොහෝ ගැටුම් හටගන්නේ අසම්පූර්ණ තොරතුරු හා සැකය නිසා වන අතර පැහැදිලි කිරීමෙන් විශ්වාසය ඇතිවේ."),
    q("අල්ලස් හෝ දූෂණ චෝදනා විමර්ශන කොමිෂන් සභාව (CIABOC) වෙත පුරවැසියන්ට පැමිණිලි කිරීමේදී ලබාදෙන ආරක්ෂාව කුමක්ද?", "පැමිණිලිකරුගේ හා තොරතුරු ලබාදෙන්නාගේ අනන්‍යතාව රහසිගතව ආරක්ෂා කිරීම", "පැමිණිලිකරු පුවත්පතේ පළ කිරීම", "පැමිණිලිකරුට දඩයක් නියම කිරීම", "රැකියාවෙන් ඉවත් කිරීම", "භීතියකින් තොරව දූෂණ වාර්තා කිරීමට හැකි වන සේ විමර්ශන ආයතන තොරතුරු ලබාදෙන්නන් ආරක්ෂා කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක 'සිවිල් සමාජ සංවිධාන' යහපාලනය උදෙසා ඉටු කරන ප්‍රධාන මුරකාර කාර්යය කුමක්ද?", "රාජ්‍ය වියදම්, මැතිවරණ හා මානව හිමිකම් අධීක්ෂණය කර මහජනතාව දැනුවත් කිරීම", "රජයේ මුදල් අච්චු ගැසීම", "අධිකරණ නඩු අවලංගු කිරීම", "පොලිස් නිලධාරීන් අත්අඩංගුවට ගැනීම", "ස්වාධීන මාධ්‍ය හා සිවිල් සමාජය පාලකයන්ගේ වගවීම නිරන්තරයෙන් පරීක්ෂා කරයි."),
    q("තොරතුරු දැනගැනීමේ පනත යටතේ රජයේ පාසලක විදුහල්පතිවරයෙකුගෙන් පාසල් සංවර්ධන සමිති ගිණුම් වාර්තා ඉල්ලා සිටිය හැකිද?", "ඔව්, පාසල පොදු අධිකාරියක් වන බැවින් මූල්‍ය විනිවිදභාවය වෙනුවෙන් ඉල්ලා සිටිය හැක", "නැත, පාසල් රහස් ලේඛනයකි", "නැත, ශ්‍රේෂ්ඨාධිකරණ අවසරය අවශ්‍යය", "නැත, 5 වගන්තියෙන් සම්පූර්ණයෙන් තහනම්ය", "රජයේ පාසල් මහජන අරමුදල් ලබන පොදු අධිකාරීන් වන බැවින් මූල්‍ය හා පරිපාලන තොරතුරු ලබාගත හැක."),
    q("රටේ ව්‍යවස්ථාවේ සඳහන් 'ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව' සඳහා පාර්ලිමේන්තුව නියෝජනය නොකරන සිවිල් සමාජ සාමාජිකයන් තිදෙනෙකු ඇතුළත් කිරීමේ අරමුණ කුමක්ද?", "පක්ෂ දේශපාලනයෙන් පරිබාහිරව ස්වාධීන, විද්වත් හා අපක්ෂපාතී මතයක් පත්වීම්වලට එක් කිරීම", "සභාවේ සාමාජිකයන් වැඩි කර වැටුප් ගෙවීම", "විපක්ෂය ඉවත් කිරීම", "මැතිවරණ කොමිසම වැසීම", "21 වන සංශෝධනයේ සිවිල් නියෝජිතයන් 3 දෙනා ස්වාධීන ආයතන පත්වීම්වල විශ්වසනීයත්වය තහවුරු කරයි."),
    q("ගැටුමක් විසඳීමේදී 'පරානුභූතියෙන් සවන් දීම' (Empathetic Listening) මඟින් ලැබෙන වාසිය කුමක්ද?", "අනෙක් පුද්ගලයාගේ බිය, වේදනාව හා අපේක්ෂාවන් අවබෝධ කරගෙන සුහද එකඟතාවකට පැමිණීම", "තර්කයෙන් අනෙකා බියගැන්වීම", "කතා කරන විට මැදින් පැන බාධා කිරීම", "පෞද්ගලික දුර්වලතා සමච්චලයට ලක් කිරීම", "සහකම්පනයෙන් සවන් දීම අනෙකාට තමන්ට ගරු කරන බව දැනී ගැටුම්කාරී ආතතිය පහව යයි."),
    q("නීතියේ ආධිපත්‍යය බිඳ වැටුණු සමාජයක ඇතිවිය හැකි ප්‍රධානතම අහිතකර ප්‍රතිඵලය කුමක්ද?", "ශක්තිමත් අය දුර්වලයන් පෙළීම, දූෂණය ඉහළ යාම හා පුරවැසි සුරක්ෂිතභාවය නැති වීම", "සමාජ සාධාරණත්වය ඉහළ යාම", "ආර්ථික ස්ථාවරත්වය ශක්තිමත් වීම", "අධිකරණ ස්වාධීනත්වය වැඩි වීම", "සැමට සමානව නීතිය ක්‍රියාත්මක නොවූ විට අරාජිකත්වය හා අසමානතාව සමාජයේ රජ කරයි."),
    q("රාජ්‍ය සේවයේ 'වැරදි පරිපාලනය' (Maladministration) යන්නට උදාහරණයක් වන්නේ පහත සඳහන් කුමක්ද?", "නිසි හේතුවක් නොමැතිව මාස ගණනාවක් පුරවැසියෙකුගේ අයදුම්පතක් ප්‍රමාද කිරීම හා නොසලකා හැරීම", "වලංගු බලපත්‍රයක් නියමිත දිනට නිකුත් කිරීම", "පුරවැසි ප්‍රඥප්තිය ප්‍රදර්ශනය කිරීම", "විවෘත ටෙන්ඩර් කැඳවීම", "ප්‍රමාදය, පක්ෂග්‍රාහී බව, වැරදි තොරතුරු දීම හා රළු ලෙස සැලකීම වැරදි පරිපාලනයේ ලක්ෂණ වේ."),
    q("පළාත් පාලන ආයතනයක හෝ රාජ්‍ය දෙපාර්තමේන්තුවක 'තොරතුරු දැනගැනීමේ නිලධාරියා' කවුරුන් විය යුතුද?", "ආයතනයේ තොරතුරු වෙත ප්‍රවේශය ඇති වගකිවයුතු නිලධාරියෙකු", "වෙනත් රටක තානාපතිවරයෙකු", "ප්‍රදේශයේ ඕනෑම පාසල් සිසුවෙකු", "බාහිර පෞද්ගලික වෙළෙන්දෙකු", "RTI පනතේ 23 වගන්තිය අනුව පොදු අධිකාරියේ නිලධාරියෙකු තොරතුරු නිලධාරි ලෙස පත් කළ යුතුය."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පාලකයන් අතර 'සංවරණය හා විගණනය' නොමැති වුවහොත් ඇතිවන තත්ත්වය කුමක්ද?", "රාජ්‍ය මුදල් නාස්තිය, අල්ලස් හා අත්තනෝමතික පාලනය ඉහළ යාම", "රට සීඝ්‍රයෙන් සංවර්ධනය වීම", "පුරවැසි විශ්වාසය උපරිම වීම", "අධිකරණ නඩු නැති වීම", "වගවීමක් හා පරීක්ෂාවක් නොමැති බලය නිරන්තරයෙන්ම දූෂණයට යොමු වේ."),
    q("ගැටුමකදී 'තාවකාලික සටන් විරාමයක් හෝ විවේකයක්' (Cooling-off Period) ලබාගැනීම ප්‍රයෝජනවත් වන්නේ ඇයි?", "දැඩි කෝපයෙන් හා ආවේගයෙන් ගන්නා විනාශකාරී තීරණ වළක්වා සන්සුන්ව සිතීමට ඉඩ ලැබෙන බැවිනි", "ගැටුම අමතක කර නොසලකා හැරීමට", "ආයුධ රැස් කර ගැනීමට", "සමථ මණ්ඩලය වසා දැමීමට", "ආවේගශීලී අවස්ථාවලදී මොහොතක විරාමයක් ගැනීමෙන් තාර්කික බුද්ධියෙන් විසඳුම් සෙවිය හැක."),
    q("රටේ පාසල් අධ්‍යාපන පද්ධතිය තුළ යහපාලන මූලධර්ම ප්‍රායෝගිකව ඉගෙනීමට සිසුන්ට අවස්ථාව ලැබෙන අවස්ථාවක් කුමක්ද?", "විද්‍යාලීය සමිති සමාගම්වල ගිණුම් විනිවිදභාවයෙන් ඉදිරිපත් කිරීම හා ප්‍රජාතන්ත්‍රවාදී නිලවරණ පැවැත්වීම", "විභාග ප්‍රශ්න පත්‍ර පිට කිරීම", "පාසල් පුස්තකාලය වසා තැබීම", "පන්ති නායකයන් ඒකාධිපති ලෙස ක්‍රියා කිරීම", "පාසල් සමිතිවල අයවැය හා නායකත්ව තේරීම් පාරදෘශ්‍යව කිරීම යහපාලනයට හොඳම පුහුණුවකි."),
    q("පෞද්ගලික අයිතිවාසිකම් හා මහජන යහපත අතර සමතුලිතතාව රැකීම සඳහා RTI කොමිෂන් සභාව ක්‍රියා කරන ආකාරය කුමක්ද?", "ප්‍රතික්ෂේපිත තොරතුරු දෙපාර්ශ්වයේ කරුණු අසා මහජන යහපත මත හෙළි කළ යුතුදැයි තීරණය කිරීම", "සෑම රාජ්‍ය ලිපියක්ම වසා තැබීම", "ජාතික ආරක්ෂක රහස් ප්‍රසිද්ධ කිරීම", "අභියාචනා විභාග නොකර ඉවත දැමීම", "අර්ධ අධිකරණමය ස්වාධීන ආයතනයක් ලෙස RTI කොමිසම තොරතුරු අයිතිය හා ව්‍යතිරේක සමතුලිත කරයි."),
    q("ශ්‍රී ලංකාවේ දූෂණ විරෝධී පනත යටතේ 'රාජ්‍ය නිලධාරීන්ගේ අයථා වත්කම් උපයා ගැනීම' සම්බන්ධයෙන් පවතින නීතිමය තත්ත්වය කුමක්ද?", "නීත්‍යානුකූල ආදායමෙන් පැහැදිලි කළ නොහැකි වත්කම් රැස් කිරීම වරදක් වන අතර ඒවා රාජසන්තක කළ හැක", "ඕනෑම අයුතු ආකාරයෙන් ධනය රැස් කිරීම නීත්‍යානුකූල වේ", "පරීක්ෂණ පැවැත්විය හැක්කේ විදේශ පොලිසියට පමණි", "විනිසුරුවරුන්ට මෙම නීතිය අදාළ නොවේ", "නිල බලය අයුතු ලෙස භාවිත කර උපයන අසාමාන්‍ය වත්කම් නීතියෙන් ප්‍රශ්න කර රාජසන්තක කළ හැක."),
    q("ගැටුමක් විසඳීමේදී 'ආකල්පමය වෙනසක්' ඇති කිරීම සැමවිටම ප්‍රධාන වන්නේ ඇයි?", "බාහිර ගිවිසුම් අත්සන් කළද සැකය හා වෛරය ඉවත් නොවුණහොත් සාමය ස්ථිර නොවන බැවිනි", "කඩදාසි මිල වැඩි බැවිනි", "අධිකරණ විනිසුරුවරුන් අඩු නිසා", "නීති සම්පාදනය කළ නොහැකි බැවිනි", "හදවතින්ම එකිනෙකා පිළිගෙන සමාව දීම හා ගෞරවය ගොඩනැගීම සැබෑ සංහිඳියාවයි."),
    q("රටේ පුරවැසියන්ට පොදු සේවාවන් ලබාගැනීමේදී යහපාලනයේ 'ඵලදායීතාව' මැනිය හැකි සරල උදාහරණයක් කුමක්ද?", "ජාතික හැඳුනුම්පතක් හෝ විදේශ ගමන් බලපත්‍රයක් එක් දිනකින් හෝ නියමිත කෙටි දිනකින් අල්ලසකින් තොරව ලැබීම", "මාස හයක් කාර්යාලයට රස්තියාදු වීම", "අතරමැදියන්ට අමතර මුදල් ගෙවීම", "ලිපිගොනු අස්ථානගත වීම", "නියමිත ප්‍රමිතියෙන් හා කාලරාමුව තුළ ජනතා අවශ්‍යතාව ඉටු වීම යහපාලනයේ ඵලදායීතාවයි."),
    q("නීතියේ ආධිපත්‍යය අනුව පාර්ලිමේන්තුව විසින් පනවන ලද නීතියක් කිසිදු පුද්ගලයෙකුට හෝ නිලධාරියෙකුට පෞද්ගලිකව අත්හිටුවිය නොහැක්කේ ඇයි?", "නීතිය වෙනස් කිරීමේ හෝ අවලංගු කිරීමේ බලය විධිමත් ව්‍යවස්ථාදායක ක්‍රියාදාමයට පමණක් අයත් බැවිනි", "නීති පොත් මුද්‍රණය කිරීමට නොහැකි නිසා", "පොලිස් නිලධාරීන් නිවාඩු ගන්නා නිසා", "සමථ මණ්ඩල එයට විරුද්ධ නිසා", "විධායක නිලධාරීන්ගේ කැමැත්ත මත නීති අත්හිටුවීම 1689 ඉංග්‍රීසි අයිතිවාසිකම් පනතේ සිටම ප්‍රතික්ෂේප විය."),
    q("ශ්‍රී ලංකාවේ 'ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව' විසින් ස්වාධීන කොමිෂන් සභාවලට අමතරව අනුමත කරන ඉහළම අධිකරණ හා රාජ්‍ය තනතුරු මොනවාද?", "අගවිනිසුරු, ශ්‍රේෂ්ඨාධිකරණ හා අභියාචනාධිකරණ විනිසුරුවරුන්, නීතිපති, පොලිස්පති හා විගණකාධිපති", "ග්‍රාම නිලධාරීන් සහ පාසල් ගුරුවරුන්", "පෞද්ගලික බැංකු කළමනාකරුවන්", "ප්‍රාදේශීය සභා සභාපතිවරුන්", "41ඇ වගන්තිය අනුව මෙම ඉහළ තනතුරු ජනාධිපතිවරයා පත් කිරීමට පෙර ව්‍යවස්ථා සභාවේ අනුමැතිය ලැබිය යුතුය."),
    q("යහපාලනය තහවුරු වූ සමාජයක 'පුරවැසියා' යනු කවරෙක්ද?", "අයිතිවාසිකම් ගැන මෙන්ම යුතුකම් හා රාජ්‍ය වගවීම ගැනද සැලකිලිමත් වන සක්‍රීය කොටස්කරුවෙකි", "නිහඬව සියලු දූෂණ ඉවසා සිටින අයෙකි", "බදු නොගෙවා රජයේ දේපළ විනාශ කරන්නෙකි", "මැතිවරණ පමණක් වර්ජනය කරන්නෙකි", "යහපාලනය ආණ්ඩුවෙන් පමණක් නොව සක්‍රීය, නීතිගරුක හා විමසිලිමත් පුරවැසියන්ගෙන් ගොඩනැගෙන දෙයකි."),
    q("ගැටුමකදී 'සාමකාමී සන්නිවේදනය' (Non-violent Communication) සඳහා අත්‍යවශ්‍ය අංග හතර කුමක්ද?", "නිරීක්ෂණය, හැඟීම, අවශ්‍යතාව සහ ගෞරවනීය ඉල්ලීම", "චෝදනාව, කෝපය, තර්ජනය සහ දඬුවම", "මඟහැරීම, බොරුව, සැකය සහ නිහඬතාව", "වෛරය, පළිගැනීම, ප්‍රචාරය සහ බලහත්කාරය", "මාර්ෂල් රෝසන්බර්ග්ගේ ආකෘතිය අනුව කරුණු නිරීක්ෂණය කර ගෞරවනීයව ඉල්ලීම ඉදිරිපත් කිරීම ගැටුම් සමනය කරයි."),
    q("රටක අධිකරණය, පාර්ලිමේන්තුව, විගණකාධිපති සහ නිදහස් මාධ්‍ය එක්ව ක්‍රියා කිරීමෙන් ශක්තිමත් වන පොදු අරමුණ කුමක්ද?", "යහපාලනය, නීතියේ ආධිපත්‍යය සහ පුරවැසි විශ්වාසය තහවුරු වීම", "ඒකාධිපති පාලනයක් බිහිවීම", "විපක්ෂය සම්පූර්ණයෙන් අහෝසි වීම", "රාජ්‍ය ආදායම් විනාශ වීම", "රාජ්‍ය ආයතනවල අන්‍යෝන්‍ය සංවරණය හා මහජන විමසිලිමත් බව ප්‍රජාතන්ත්‍රවාදී යහපාලනයේ ආරක්ෂාවයි."),
    q("සමථ මණ්ඩලයකදී දෙපාර්ශ්වයම එකඟතාවයකට පැමිණි පසු අත්සන් කරන 'සමථ ගිවිසුමේ' නීතිමය වැදගත්කම කුමක්ද?", "පාර්ශ්ව දෙකටම එකඟ වූ කොන්දේසි ඉටු කිරීමට සදාචාර හා නීතිමය බැඳීමක් ඇති වීම", "එය අනෙක් රටවලට පමණක් වලංගු වීම", "විනිසුරුවරුන්ට සිරදඬුවම් දීමට හැකි වීම", "සමථකරුට මුදල් ලැබීම", "එකඟතාව කඩ කළහොත් ඒ බව අධිකරණය හමුවේ ඉදිරිපත් කර ඉදිරි නීතිමය ක්‍රියාමාර්ග ගත හැක."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පරිපාලන අසාධාරණයක් සිදුවූ විට 'අධිකරණ සමාලෝචනය' (Judicial Review of Administrative Action) මඟින් සිදු කරන්නේ කුමක්ද?", "රාජ්‍ය නිලධාරීන්ගේ තීරණ නීතිවිරෝධී, අසාධාරණ හෝ පටිපාටියට පටහැනි නම් අවලංගු කිරීම", "නව රාජ්‍ය බදු පැනවීම", "ඡන්දදායකයන් ලියාපදිංචි කිරීම", "අමාත්‍ය මණ්ඩලය පත් කිරීම", "අභියාචනාධිකරණය රීට් ආඥා මඟින් විධායක නිලධාරීන්ගේ අත්තනෝමතික පරිපාලන තීරණ පාලනය කරයි."),
    q("රජයේ ප්‍රසම්පාදන හා සංවර්ධන ව්‍යාපෘතිවල 'ගුණාත්මක බව හා කාලරාමුව' රැකීම සඳහා පළාත් මට්ටමින් ගත යුතු යහපාලන පියවර කුමක්ද?", "අධීක්ෂණ වාර්තා ප්‍රසිද්ධ කිරීම, විගණනය හා ප්‍රජා නිරීක්ෂණයට ඉඩ දීම", "ගිවිසුම් සදහටම රහසිගතව තැබීම", "ටෙන්ඩර් නොමැතිව මිතුරන්ට දීම", "විගණකාධිපති පරීක්ෂණ තහනම් කිරීම", "ව්‍යාපෘති පුවරු මඟින් මුදල් ප්‍රතිපාදන හා අවසන් දින ප්‍රදර්ශනය කිරීම විනිවිදභාවය ඉහළ නංවයි."),
    q("ශ්‍රී ලංකාවේ 2016 තොරතුරු දැනගැනීමේ පනත යටතේ 'දින 14 තුළ තොරතුරු ලබාදීමේ නීතිය' රජයේ කාර්යාලවලට ඉගැන්වූ නව සංස්කෘතිය කුමක්ද?", "තොරතුරු සැඟවීම වෙනුවට වගවීමෙන් යුතුව තොරතුරු පවත්වාගැනීම හා හෙළි කිරීමේ සංස්කෘතිය", "සියලු ලිපිගොනු පිළිස්සීම", "විදේශිකයන්ට පමණක් පිළිතුරු දීම", "මහජන කවුළු වසා දැමීම", "රජයේ තොරතුරු නිලධාරීන්ගේ පෞද්ගලික දේපළ නොව මහජන භාරයක් බව RTI පනතෙන් තහවුරු විය."),
    q("ගැටුමක් විසඳීමේදී 'ප්‍රතිපත්තිමය සාකච්ඡාව' (Principled Negotiation) හඳුන්වා දුන් ප්‍රධාන මූලධර්මය කුමක්ද?", "ස්ථාවරයන්ට නොව සැබෑ අවශ්‍යතාවලට අවධානය යොමු කර වෛෂයික නිර්ණායක මත තීරණ ගැනීම", "තර්ජන එල්ල කර අනෙකා බියගැන්වීම", "පෞද්ගලික අපහාස කිරීම", "දිගින් දිගටම නිහඬව සිටීම", "රොජර් ෆිෂර් හා විලියම් යූරි දැක්වූ මෙම ක්‍රමය දෙපාර්ශ්වයටම සාධාරණ ගිවිසුම් ගොඩනඟයි."),
    q("රටේ පාර්ලිමේන්තු මැතිවරණයකින් පසු පත්වන කැබිනට් අමාත්‍යවරයෙකු පවා රාජ්‍ය මුදල් වැය කිරීමේදී පාර්ලිමේන්තුවට වගකිව යුතු වීමෙන් රැකෙන්නේ කුමක්ද?", "මූල්‍ය වගවීම හා ප්‍රජාතන්ත්‍රවාදී යහපාලනය", "ඒකාධිපති මූල්‍ය බලය", "බදු අය කිරීම තහනම් වීම", "අධිකරණ සේවා කොමිසම", "148 වගන්තිය අනුව මහජන මුදල් පිළිබඳ පූර්ණ පාලනය පාර්ලිමේන්තුව සතු වීම යහපාලන පදනමකි."),
    q("ශ්‍රී ලංකාවේ 'විද්‍යුත් තැපැල් හා මාර්ගගත පැමිණිලි පද්ධති' රාජ්‍ය ආයතනවල ස්ථාපිත කිරීමෙන් දුරබැහැර පුරවැසියන්ට ලැබුණු වාසිය කුමක්ද?", "කොළඹට නොපැමිණ ගමේ සිටම තම අයිතිවාසිකම් හා පැමිණිලි ඉදිරිපත් කිරීමට හැකි වීම", "සියලු ප්‍රාදේශීය කාර්යාල වැසී යාම", "අධිකරණ පද්ධතිය අහෝසි වීම", "වරිපනම් බදු දෙගුණ වීම", "භූගෝලීය බාධා ජය ගනිමින් සැමට සමාන රාජ්‍ය සේවා ප්‍රවේශයක් ලැබීම ඉන් සිදුවේ."),
    q("නීතියේ ආධිපත්‍යය හා යහපාලනය අතර ඇති නොබිඳිය හැකි සම්බන්ධතාව කුමක්ද?", "නීතියේ ආධිපත්‍යය නොමැති තැන විනිවිදභාවය හෝ වගවීම හෝ සැබෑ යහපාලනයක් පැවතිය නොහැක", "නීතියේ ආධිපත්‍යය යහපාලනයට බාධාවකි", "දෙකම රාජාණ්ඩු ක්‍රමයට පමණක් අදාළය", "යහපාලනය පවතින්නේ නීතිය ඉවත් කළ විටය", "නීතිය සැමට සමානව ක්‍රියාත්මක වීම යහපාලනයේ මූලික කුළුණකි."),
    q("යහපාලනයේ මූලික ලක්ෂණයක් වන 'වගවීම' (Accountability) ප්‍රායෝගිකව රාජ්‍ය ආයතන තුළ පෙන්නුම් කරන්නේ කෙසේද?", "ගත් තීරණ, වැය කළ මුදල් හා සේවා ප්‍රතිඵල පිළිබඳව මහජනතාවට හා පාර්ලිමේන්තුවට පිළිතුරු බැඳීමෙන්", "සියලු ගිණුම් වාර්තා වසර 50ක් සැඟවීමෙන්", "මහජන පැමිණිලි ප්‍රතික්ෂේප කිරීමෙන්", "විගණකාධිපතිට ඇතුළු වීම තහනම් කිරීමෙන්", "රාජ්‍ය බලය භාවිත කරන සෑම නිලධාරියෙකුම හා පාලකයෙකුම තම ක්‍රියාවන්ට වගකිව යුතුය."),
    q("යහපාලනයේ 'විනිවිදභාවය' (Transparency) තහවුරු කිරීම සඳහා රාජ්‍ය ආයතන අනුගමනය කළ යුතු පියවරක් කුමක්ද?", "රාජ්‍ය ටෙන්ඩර් ක්‍රියාවලි, ප්‍රතිපත්ති තීරණ හා වාර්ෂික වාර්තා ජනතාවට පහසුවෙන් පරීක්ෂා කිරීමට සැලසීම", "රාජ්‍ය ලේඛන පෞද්ගලික නිවෙස්වල තබාගැනීම", "කොන්ත්‍රාත් ගිවිසුම් රහසේ අත්සන් කිරීම", "මහජනතාවට කාර්යාල පරිශ්‍රය තහනම් කිරීම", "විවෘතභාවය නිසා අක්‍රමිකතා සැඟවීම අපහසු වන අතර පුරවැසි විශ්වාසය ඉහළ යයි."),
    q("යහපාලනයේ 'ප්‍රතිචාරාත්මක බව' (Responsiveness) යන්නෙන් අදහස් කෙරෙන කාර්යය කුමක්ද?", "සාධාරණ කාලරාමුවක් තුළ පුරවැසියන්ගේ ගැටලුවලට හා අවශ්‍යතාවලට කඩිනමින් සේවා සැලසීම", "අයදුම්පත් වසර ගණනාවක් ප්‍රමාද කිරීම", "හදිසි ආපදා වෙලාවේ කාර්යාල වසා දැමීම", "දුරකථන ඇමතුම්වලට පිළිතුරු නොදීම", "පුරවැසි කේන්ද්‍රීය පරිපාලනයකදී ජනතා අපේක්ෂාවන්ට ඉක්මනින් හා ආචාරශීලීව ප්‍රතිචාර දැක්විය යුතුය."),
    q("සියලු ජන කොටස්වලට තීරණ ගැනීමේ ක්‍රියාවලියට සම්බන්ධ වීමට අවස්ථාව සලසන යහපාලන මූලධර්මය කුමක්ද?", "සහභාගිත්වය (Participation) සහ ඇතුළත් කරගැනීම", "ඒකාධිපති මධ්‍යගතකරණය", "රහස්‍ය ඒකාධිකාරය", "පක්ෂග්‍රාහී පරිපාලනය", "තරුණයන්, කාන්තාවන් හා සුළුතර ප්‍රජාවන් ඇතුළු සැමගේ හඬට සවන් දීමෙන් සාධාරණ ප්‍රතිපත්ති බිහිවේ."),
    q("නීතියේ ආධිපත්‍යය පිළිබඳ ඒ.වී. ඩයිසිගේ 'පළමු මූලධර්මය' මඟින් ප්‍රතික්ෂේප කරනු ලබන්නේ කුමක්ද?", "පාලකයන්ගේ අත්තනෝමතික බලය (Arbitrary Power) හා විධිමත් නඩු විභාගයකින් තොර දඬුවම්", "පාර්ලිමේන්තු මැතිවරණ", "ශ්‍රේෂ්ඨාධිකරණ තීන්දු", "ස්වාධීන නීතිඥ වෘත්තිය", "පැහැදිලිව පවතින නීතියක් කඩ කිරීම අධිකරණයකදී ඔප්පු වූ විට පමණක් පුරවැසියෙකුට දඬුවම් කළ හැකිය."),
    q("ඩයිසිගේ නීතියේ ආධිපත්‍යය සංකල්පයේ 'තෙවන මූලධර්මය' අනුව බ්‍රිතාන්‍යයේ පුරවැසි අයිතිවාසිකම් සුරක්ෂිත වූයේ කුමකින්ද?", "අධිකරණ විසින් තීරණය කළ සාමාන්‍ය නීතිය හා නඩු තීන්දු මගින් (Judge-made Law)", "රාජකීය ආඥාවකින් පමණක්", "හමුදා අධිකරණ නියෝගවලින්", "විදේශීය ගිවිසුම්වලින් පමණක්", "නීතිය ඉදිරියේ අධිකරණ ලබාදෙන අඛණ්ඩ ආරක්ෂාව අයිතිවාසිකම්වල සැබෑ පදනම බව ඔහු පෙන්වා දුන්නේය."),
    q("ශ්‍රී ලංකාවේ 'අල්ලස් හෝ දූෂණ චෝදනා විමර්ශන කොමිෂන් සභාව' (CIABOC) පිහිටුවීමේ ප්‍රධාන අරමුණ කුමක්ද?", "රාජ්‍ය හා පෞද්ගලික අංශයේ අල්ලස් හා දූෂණ වැළැක්වීම, විමර්ශනය කිරීම හා නඩු පැවරීම", "පළාත් පාලන මැතිවරණ පැවැත්වීම", "බදු අනුපාත තීරණය කිරීම", "ජාතික විභාග ප්‍රතිඵල නිකුත් කිරීම", "2023 දූෂණ විරෝධී පනත යටතේ CIABOC ආයතනයට පූර්ණ ස්වාධීනත්වය හා වැඩි බලතල පවරා ඇත."),
    q("රාජ්‍ය නිලධාරියෙකු 'මහජන භාරකාරත්ව මූලධර්මය' (Public Trust Doctrine) කඩ කරන අවස්ථාවක් වන්නේ කුමක්ද?", "මහජන දේපළ හා තනතුරේ බලය තම පෞද්ගලික ලාභය හෝ හිතවතුන්ගේ වාසිය සඳහා යෙදවීම", "නීතියට අනුව සාධාරණව සේවය කිරීම", "සියලු ඉල්ලුම්කරුවන්ට සමානව සැලකීම", "වාර්ෂික විගණනයට ඉඩ දීම", "ශ්‍රී ලංකා ශ්‍රේෂ්ඨාධිකරණය අවධාරණය කර ඇත්තේ රාජ්‍ය බලය ජනතාව විසින් පාලකයන්ට දෙන භාරයක් බවය."),
    q("2016 අංක 12 දරන RTI පනත යටතේ තොරතුරු ඉල්ලීමක් ප්‍රතික්ෂේප කළ විට පුරවැසියාට පළමුව අභියාචනා කළ හැක්කේ කා වෙතද?", "එම ආයතනයේම නම් කරන ලද නිලධාරියා (Designated Officer) වෙත", "ජාත්‍යන්තර අධිකරණය වෙත", "මැතිවරණ කොමිසම වෙත", "පොලිස්පති වෙත", "තොරතුරු නිලධාරියා ප්‍රතික්ෂේප කළහොත් දින 14ක් ඇතුළත නම් කළ නිලධාරියාටත් ඉන්පසු RTI කොමිසමටත් අභියාචනා කළ හැක."),
    q("තොරතුරු දැනගැනීමේ පනතේ 'දින 14 කාලසීමාව' වෙනුවට පැය 48ක් ඇතුළත තොරතුරු ලබා දිය යුතු විශේෂ අවස්ථාව කුමක්ද?", "ඉල්ලා සිටින තොරතුර පුද්ගලයෙකුගේ ජීවිතය හෝ පෞද්ගලික නිදහස පිළිබඳ වන විට", "ක්‍රිකට් තරග ප්‍රතිඵල ඉල්ලූ විට", "නව මාර්ග ව්‍යාපෘතියක් ගැන ඉල්ලූ විට", "පාසල් නිවාඩු දින ඉල්ලූ විට", "ජීවිතය හා නිදහස සම්බන්ධ හදිසි තොරතුරු පැය 48ක් ඇතුළත සැපයීම RTI පනතේ මානුෂීය ප්‍රතිපාදනයකි."),
    q("RTI පනත යටතේ 'අපරාධ විමර්ශනවලට බාධා වන තොරතුරු' හෙළි නොකිරීමට හැක්කේ ඇයි?", "සැකකරුවන් පලා යාම, සාක්ෂි විනාශ කිරීම හා යුක්තිය පසිඳලීම කඩාකප්පල් වීම වැළැක්වීමට", "රජයේ ගිණුම් සැඟවීමට", "පාසල් පෙළපොත් සැඟවීමට", "බදු අය කිරීම නැවැත්වීමට", "5(1)(ඌ) වගන්තිය අනුව සිදුවෙමින් පවතින අපරාධ පරීක්ෂණ හා සාධාරණ නඩු විභාග ආරක්ෂා කිරීම සඳහා සීමා පැනවිය හැක."),
    q("රටේ පාර්ලිමේන්තුවේ 'රාජ්‍ය ව්‍යවසාය පිළිබඳ කාරක සභාව' (COPE) මඟින් ඉටු කරන විශේෂ කාර්යය කුමක්ද?", "රාජ්‍ය සංස්ථා, මණ්ඩල හා රජය සතු සමාගම්වල මූල්‍ය කළමනාකරණය හා කාර්යක්ෂමතාව පරීක්ෂා කිරීම", "පෞද්ගලික පවුල් ආරවුල් සමථ කිරීම", "පළාත් පාලන මැතිවරණ පැවැත්වීම", "ජනාධිපති සමාව ප්‍රදානය කිරීම", "විගණකාධිපති වාර්තා පදනම් කරගෙන රාජ්‍ය ව්‍යවසායවල වංචා හා අලාභ COPE කමිටුව හරහා හෙළිදරව් කෙරේ."),
    q("පාර්ලිමේන්තුවේ 'රාජ්‍ය ගිණුම් කාරක සභාව' (COPA) මඟින් අධීක්ෂණය කරනු ලබන්නේ කුමන ආයතනද?", "රජයේ අමාත්‍යාංශ, දෙපාර්තමේන්තු, දිස්ත්‍රික් ලේකම් කාර්යාල හා පළාත් සභා මූල්‍ය කටයුතු", "පෞද්ගලික සුපිරි වෙළඳසැල් පමණි", "විදේශීය තානාපති කාර්යාල පමණි", "ක්‍රීඩා සමාජ පමණි", "පාර්ලිමේන්තුව වෙන් කළ මුදල් රජයේ දෙපාර්තමේන්තු නිසි ලෙස වැය කළේද යන්න COPA විසින් විමසා බලයි."),
    q("ශ්‍රී ලංකාවේ 'ජාතික ප්‍රසම්පාදන කොමිෂන් සභාව' පිහිටුවීමෙන් යහපාලනයට සිදුවන ප්‍රධාන යහපත කුමක්ද?", "රජයේ භාණ්ඩ මිලදී ගැනීම් හා ඉදිකිරීම් ටෙන්ඩර් සඳහා සාධාරණ, විවෘත හා දූෂණයෙන් තොර මාර්ගෝපදේශ සැකසීම", "බදු අනුපාත දෙගුණ කිරීම", "නඩු විභාග නතර කිරීම", "මැතිවරණ කල් දැමීම", "විනිවිද පෙනෙන ප්‍රසම්පාදන ක්‍රියාවලිය රජයේ මුදල් ඉතිරි කර ගුණාත්මක සංවර්ධන ව්‍යාපෘති තහවුරු කරයි."),
    q("රාජ්‍ය නිලධාරියෙකු පුරවැසියෙකුට අසාධාරණයක් කළ විට අධිකරණයට නොගොස් සහන ලබාගත හැකි ඔම්බුඩ්ස්මන් ආයතනය මුලින්ම බිහි වූ රට කුමක්ද?", "ස්වීඩනය (1809)", "චීනය", "රුසියාව", "බ්‍රසීලය", "ස්වීඩනයෙන් ඇරඹි ඔම්බුඩ්ස්මන් ක්‍රමය ශ්‍රී ලංකාවේ 1978 ව්‍යවස්ථාවේ 156 වගන්තියෙන් හඳුන්වා දෙන ලදී."),
    q("ශ්‍රී ලංකාවේ පුරවැසියෙකුට 'රාජ්‍ය සේවා කොමිෂන් සභාව' වෙත අභියාචනා කළ හැක්කේ කවර කරුණක් සම්බන්ධයෙන්ද?", "රාජ්‍ය නිලධාරියෙකුගේ පත්වීම්, උසස්වීම්, ස්ථාන මාරු හෝ විනය පරීක්ෂණවලදී සිදු වූ අසාධාරණයකදී", "වෙළඳපොළේ බඩු මිල වැඩි වූ විට", "ඉඩම් මායිම් ආරවුලකදී", "විදේශ වීසා ප්‍රතික්ෂේප වූ විට", "රාජ්‍ය සේවකයන් දේශපාලන බලපෑම්වලින් රැකගෙන සාධාරණ පරිපාලනයක් පවත්වාගැනීම මෙහි අරමුණයි."),
    q("ප්‍රචණ්ඩ නොවන ගැටුම් නිරාකරණයේදී 'පක්ෂග්‍රාහී නොවූ තුන්වන පාර්ශ්වයක්' විසඳුමක් බලෙන් නොපනවා සාකච්ඡාව මෙහෙයවන ක්‍රමය කුමක්ද?", "සමථකරණය (Mediation)", "බේරුම්කරණය (Arbitration)", "අධිකරණ නඩු විභාගය", "හමුදා අත්අඩංගුව", "සමථකරුවා පාර්ශ්ව දෙකටම ඇහුම්කන් දී ඔවුන් විසින්ම පිළිගන්නා විසඳුමක් සොයාගැනීමට උදව් කරයි."),
    q("ආරවුලක් විසඳීම සඳහා තුන්වන පාර්ශ්වයක් (බේරුම්කරුවෙකු) පත් කර ඔහු දෙන තීරණයට දෙපාර්ශ්වයම බැඳී සිටින ක්‍රමය කුමක්ද?", "බේරුම්කරණය (Arbitration)", "සාකච්ඡාව (Negotiation)", "මඟහැරීම (Avoiding)", "පැමිණිලි පෙට්ටිය", "වාණිජ හා කම්කරු ආරවුල් ඉක්මනින් විසඳීම සඳහා නීතිමය බැඳීමක් ඇති බේරුම්කරණ ක්‍රමය භාවිත කෙරේ."),
    q("ගැටුමක් විසඳීමේ 'සහයෝගීතා' (Collaborating) ප්‍රවේශය මඟින් ඇති කරන ප්‍රතිඵලය හඳුන්වන්නේ කුමන නමින්ද?", "දිනුම්-දිනුම් (Win-Win) විසඳුම", "දිනුම්-පරාජය (Win-Lose) විසඳුම", "පරාජය-පරාජය (Lose-Lose) විසඳුම", "බලහත්කාරී යටත් කිරීම", "පාර්ශ්ව දෙකේම මූලික අවශ්‍යතා සම්පූර්ණයෙන්ම හා ගෞරවනීයව ඉටු වන නිර්මාණශීලී විසඳුම Win-Win වේ."),
    q("ගැටුමකදී පාර්ශ්ව දෙකම තම ඉල්ලීම්වලින් කොටසක් කැප කර මැද ස්ථාවරයකට එකඟ වීම කුමන විසඳුම් ක්‍රමයද?", "සම්මුතිගත වීම / මැදහත් එකඟතාව (Compromising)", "බලහත්කාරයෙන් ජය ගැනීම", "සම්පූර්ණයෙන් පලා යාම", "යුද ප්‍රකාශ කිරීම", "කාලය සීමිත විට හෝ පාර්ශ්ව දෙකටම යම් පමණකට සෑහීමට පත්වීමට අවශ්‍ය විට Compromising ක්‍රමය යොදාගනී."),
    q("පවුලේ හෝ පාසලේ ගැටුමක් හටගත් මුල් අවස්ථාවේදීම විසඳා ගැනීම වැදගත් වන්නේ ඇයි?", "සුළු මතභේදයක් ප්‍රචණ්ඩත්වය හා දිගුකාලීන වෛරය දක්වා උත්සන්න වීම වළක්වා ගැනීමට", "සියලු දෙනා අධිකරණයට යැවීමට", "පාසල වසා දැමීමට", "දඬුවම් දෙගුණ කිරීමට", "ගැටුමක් කුඩා අවධියේදීම සංවාදයෙන් නිරාකරණය කිරීමෙන් සබඳතා බිඳ වැටීම වළක්වයි."),
    q("ශ්‍රී ලංකාවේ ප්‍රජා සමථ මණ්ඩල වෙත යොමු කළ හැකි සිවිල් ආරවුලක් සඳහා උදාහරණයක් වන්නේ කුමක්ද?", "රුපියල් මිලියනයකට අඩු ණය මුදල් හෝ ඉඩම් මායිම් පිළිබඳ අසල්වැසි ආරවුල්", "මනුෂ්‍ය ඝාතන නඩු", "රාජ්‍ය ද්‍රෝහී කුමන්ත්‍රණ", "ජාත්‍යන්තර ගුවන් සේවා නඩු", "මුදල් ඉතිරි කරමින් ගමේම සුහදව සුළු සිවිල් හා ඉඩම් ආරවුල් විසඳා ගැනීමට සමථ මණ්ඩල උපකාරී වේ."),
    q("සමථ මණ්ඩලයක් ඉදිරියේ ආරවුලක් සාර්ථකව නිරාකරණය නොවුණහොත් සමථ මණ්ඩලය නිකුත් කරන ලියවිල්ල කුමක්ද?", "සමථ නොවීමේ සහතිකය (Certificate of Non-Settlement)", "සිරදඬුවම් නියෝගය", "මරණ වරෙන්තුව", "විදේශ ගමන් බලපත්‍රය", "නීතියෙන් නියමිත බොහෝ සිවිල් නඩු අධිකරණයේ පැවරීමට පෙර මෙම සහතිකය ඉදිරිපත් කිරීම අනිවාර්ය වේ."),
    q("සාමකාමී ගැටුම් නිරාකරණයේදී 'සක්‍රීය සවන්දීම' (Active Listening) පුරුදු කරන අයෙකු දක්වන හැසිරීම කුමක්ද?", "බාධා නොකර අවධානයෙන් අසා සිට කියූ දේ නිවැරදිව තේරුම් ගත්තාදැයි තහවුරු කිරීම", "අනෙකා කතා කරද්දී කෑගසා බාධා කිරීම", "දුරකථනය දෙස බලා සිටීම", "සිනාසී මගහැර යාම", "සක්‍රීය සවන්දීම මඟින් අනෙකාට ඇති කෝපය අඩු වී විශ්වාසය ගොඩනැගේ."),
    q("සමාජ ගැටුම් නිර්මාණය වීමට හේතු වන 'ව්‍යුහාත්මක ප්‍රචණ්ඩත්වය' (Structural Violence) ලෙස ජොහාන් ගැල්ටුං හැඳින්වූයේ කුමක්ද?", "ආයතනික වෙනස් කොට සැලකීම, දිළිඳුකම හා සමාන අවස්ථා අහිමි කිරීම වැනි අසාධාරණ සමාජ ක්‍රම", "පාරේ සිදුවන රථවාහන අනතුරු පමණි", "ස්වභාවික භූමිකම්පා පමණි", "පාසල් ක්‍රීඩා තරග පමණි", "භෞතික ආයුධ නැතිව වුවද අසාධාරණ සමාජ ආර්ථික ව්‍යුහයන් ජනතාවගේ මූලික අවශ්‍යතා වළක්වයි."),
    q("සාම අධ්‍යයනයේදී 'ඍණාත්මක සාමය' (Negative Peace) සහ 'ධනාත්මක සාමය' (Positive Peace) අතර වෙනස කුමක්ද?", "ඍණාත්මක සාමය යනු යුද්ධය නැතිවීම පමණක් වන අතර ධනාත්මක සාමය යනු යුක්තිය, සමානාත්මතාව හා සංහිඳියාව පැවතීමයි", "දෙකම යුද්ධය ආරම්භ කිරීමට සම්බන්ධය", "ධනාත්මක සාමය යනු අවි ආයුධ වැඩි කිරීමයි", "ඍණාත්මක සාමය යනු සියලු පාසල් වැසීමයි", "තුවක්කු නිහඬ වූ පමණින් සැබෑ සාමය ඇති නොවන අතර ගැටුමට මුල් වූ සමාජ අසාධාරණ විසඳිය යුතුය."),
    q("නීතියේ ආධිපත්‍යය අනුව 'පසුකාලීනව බලපවත්වන දණ්ඩ නීති' (Retroactive Criminal Laws) පැනවීම අසාධාරණ වන්නේ ඇයි?", "යම් ක්‍රියාවක් කරන අවස්ථාවේ එය නීති විරෝධී නොවුණේ නම් පසුව නීති හදා දඬුවම් කිරීම මූලික යුක්තියට පටහැනි බැවිනි", "රජයේ මුද්‍රණාලයේ කඩදාසි අඩු බැවිනි", "නීතිඥයන් අකමැති බැවිනි", "විදේශිකයන්ට පමණක් එය හිතකර බැවිනි", "1978 ව්‍යවස්ථාවේ 13(6) වගන්තියෙන්ද පසුපසට බලපාන දණ්ඩ නීති මඟින් දඬුවම් කිරීම තහනම් කර ඇත."),
    q("විනිවිදභාවය හා නීතියේ ආධිපත්‍යය රැකීමට අධිකරණ නඩු විභාග සාමාන්‍යයෙන් 'විවෘත අධිකරණයක' (Open Court) පවත්වන්නේ ඇයි?", "අධිකරණ ක්‍රියාවලිය සාධාරණ හා පක්ෂග්‍රාහී නොවන බව මහජනතාවට දැක බලා ගැනීමට", "රූපවාහිනී දැන්වීම් ප්‍රචාරයට", "පොලිසියට විවේක ගැනීමට", "සාක්ෂිකරුවන් බිය ගැන්වීමට", "යුක්තිය ඉටු විය යුතු පමණක් නොව ඉටු වන බව පෙනෙන්නටද තිබිය යුතුය යන මූලධර්මය ඉන් සුරැකේ."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලනයක 'දූෂණ අවදානම් අවම කිරීමට' රාජ්‍ය සේවයේ පත්වීම් හා උසස්වීම් ලබාදිය යුත්තේ කුමන පදනමකින්ද?", "දක්ෂතාව, අධ්‍යාපන සුදුසුකම් හා තරග විභාග (Meritocracy) පදනමින්", "දේශපාලන හිතවත්කම් මත", "මුදල් ගෙවීම් මත", "පවුල් ඥාතිත්වය මත", "සුදුස්සාට සුදුසු තැන ලැබෙන විට රාජ්‍ය සේවයේ කාර්යක්ෂමතාව හා අපක්ෂපාතීත්වය ඉහළ යයි."),
    q("රාජ්‍ය ආයතනවල 'පුරවැසි ප්‍රඥප්තිය' (Citizen's Charter) ප්‍රදර්ශනය කිරීමෙන් ජනතාවට ලැබෙන වාසිය කුමක්ද?", "ලැබිය යුතු සේවා, ගාස්තු, අවශ්‍ය ලියවිලි හා ගතවන කාලය කලින්ම දැන සේවය ඉල්ලා සිටීමට හැකි වීම", "කාර්යාල නිලධාරීන්ගේ නිවාඩු දින වැඩි වීම", "සේවා ගාස්තු රහසිගත වීම", "මහජන පැමිණිලි තහනම් වීම", "පුරවැසි ප්‍රඥප්තිය රාජ්‍ය සේවයේ ප්‍රමිතිය හා වගවීම ප්‍රසිද්ධ කරන සමාජ ගිවිසුමකි."),
    q("යහපාලනය තහවුරු කිරීමේදී 'තොරතුරු තාක්ෂණය හා ඊ-රාජ්‍ය පාලනය' (E-Governance) වැදගත් කාර්යභාරයක් ඉටු කරන්නේ කෙසේද?", "මාර්ගගත පද්ධති හරහා සේවා කඩිනම් කරමින් මිනිස් මැදිහත්වීම් හා අල්ලස් ඉඩකඩ අඩු කිරීමෙන්", "සියලු ලිපිගොනු අතින් ලිවීම වැඩි කිරීමෙන්", "අන්තර්ජාලය විසන්ධි කිරීමෙන්", "පුරවැසියන්ට රජයේ වෙබ් අඩවි තහනම් කිරීමෙන්", "ඩිජිටල්කරණය මඟින් උප්පැන්න, ගමන් බලපත්‍ර හා බදු ගෙවීම් ඉක්මනින් හා පාරදෘශ්‍යව කළ හැක."),
    q("ශ්‍රී ලංකාවේ 'වත්කම් හා බැරකම් ප්‍රකාශ' (Declaration of Assets and Liabilities) ඉදිරිපත් කිරීම නීතියෙන් අනිවාර්ය කර ඇත්තේ කාටද?", "ජනාධිපති, අගමැති, ඇමතිවරුන්, මන්ත්‍රීවරුන්, විනිසුරුවරුන් හා ඉහළ රාජ්‍ය නිලධාරීන්ට", "පාසල් ශිෂ්‍යයන්ට පමණි", "විදේශ සංචාරකයන්ට පමණි", "ගොවීන්ට පමණි", "බලයේ සිටියදී අයථා ලෙස ධනය රැස් කිරීම වැළැක්වීම සඳහා වත්කම් ප්‍රකාශ කිරීම දූෂණ විරෝධී පනතින් අනිවාර්ය කර ඇත."),
    q("දූෂණයට එරෙහිව හඬ නඟන පුරවැසියන් හෝ නිලධාරීන් ආරක්ෂා කිරීමේ නීතිමය සංකල්පය කුමක්ද?", "තොරතුරු හෙළි කරන්නන් ආරක්ෂා කිරීම (Whistleblower Protection)", "රාජ්‍ය රහස් වාරණය", "අපරාධ නඩු අත්හිටුවීම", "දේශපාලන මුක්තිය", "ආයතන තුළ සිදුවන වංචා පෙන්වා දෙන අවංක පුද්ගලයන්ට සේවා හිංසන හා තර්ජනවලින් රැකවරණය දිය යුතුය."),
    q("පවුලේ හෝ පන්ති කාමරයේ ඇතිවන ගැටුමකදී 'තීරණ ගැනීම පමා කිරීම' (Cooling-off Period) උපකාරී වන්නේ ඇයි?", "දැඩි කෝපය හා හැඟීම්බර ආවේග පහව ගොස් තාර්කිකව හා සාධාරණව සිතීමට ඉඩ ලැබෙන බැවිනි", "අනෙකාට පහර දීමට සැලසුම් කිරීමට", "සදහටම කතා නොකර සිටීමට", "වැරදි කටකතා පැතිරවීමට", "ආවේගශීලී අවස්ථාවල ගන්නා තීරණ ගැටුම් තවත් දරුණු කරන බැවින් මොහොතක් සන්සුන් වීම ඵලදායී වේ."),
    q("සංස්කෘතික හෝ වාර්ගික ගැටුම් වැළැක්වීම සඳහා අධ්‍යාපන පද්ධතිය තුළ 'විවේචනාත්මක චින්තනය' (Critical Thinking) වර්ධනය කළ යුත්තේ ඇයි?", "කටකතා, වෛරී ප්‍රචාර හා අන්තවාදී මතවලට නොරැවටී සත්‍ය කරුණු විමසා බැලීමට හැකි වන බැවිනි", "පාඩම් කටපාඩම් කිරීම වැඩි කිරීමට", "සියලු විද්‍යා විෂයන් ඉවත් කිරීමට", "විවිධ මත ඉවසීම නැති කිරීමට", "තාර්කිකව සිතන පුරවැසියන් වෛරී දේශපාලනයට හෝ ප්‍රචණ්ඩත්වයට පහසුවෙන් ගොදුරු නොවේ."),
    q("ශ්‍රී ලංකාවේ 'ජාතික සමගිය හා සංහිඳියාව' උදෙසා සෑම පුරවැසියෙකුම පිළිපැදිය යුතු යහපාලන හා සිවිල් ගුණාංගයක් කුමක්ද?", "විවිධත්වයට ගරු කිරීම, සමාන අයිතිවාසිකම් පිළිගැනීම හා සාමකාමී සංවාදයෙන් ගැටලු විසඳීම", "වෙනස් මත දරන්නන් බලෙන් නිහඬ කිරීම", "ජාතිවාදී ප්‍රකාශ පළ කිරීම", "පොදු දේපළවලට හානි කිරීම", "බහුසංස්කෘතික රටක ස්ථාවර සාමය රැඳී ඇත්තේ පුරවැසියන්ගේ ඉවසීම හා නීතිගරුකභාවය මතය."),
    q("නීතියේ ආධිපත්‍යය අනුව 'පොලිස් නිලධාරීන් පවා සැකකරුවෙකු අත්අඩංගුවට ගැනීමේදී' අනුගමනය කළ යුතු ක්‍රියාපටිපාටිය කුමක්ද?", "නීත්‍යානුකූල හේතු දන්වා වධහිංසාවෙන් තොරව පැය 24ක් ඇතුළත මහේස්ත්‍රාත්වරයෙකු ඉදිරියට පැමිණවීම", "හේතු නොකියා වසර ගණනාවක් සඟවා තැබීම", "පහර දී බලෙන් පාපොච්චාරණ ගැනීම", "පවුලේ අයට නොදන්වා සිටීම", "1978 ව්‍යවස්ථාවේ 11 හා 13 වගන්ති අනුව අත්තනෝමතික අත්අඩංගුවට ගැනීම් හා වධහිංසා සපුරා තහනම්ය."),
    q("පුරවැසියෙකුට ශ්‍රී ලංකා මානව හිමිකම් කොමිෂන් සභාවට (HRCSL) පැමිණිල්ලක් ඉදිරිපත් කළ හැක්කේ කුමන අවස්ථාවකදීද?", "රාජ්‍ය ආයතනයක් හෝ නිලධාරියෙකු විසින් තම මූලික අයිතිවාසිකමක් උල්ලංඝනය කළ හෝ කිරීමට ආසන්න විට", "පෞද්ගලික වෙළඳසැලකින් වැඩි මිලට භාණ්ඩ විකුණූ විට", "ක්‍රිකට් කණ්ඩායම පරාජය වූ විට", "පෞද්ගලික නිවසක තීන්ත ආලේප කිරීමේදී", "1996 අංක 21 පනත යටතේ මූලික අයිතිවාසිකම් කඩවීම් විමර්ශනය කර නිර්දේශ දීමට කොමිසම ක්‍රියා කරයි."),
    q("යහපාලනය තුළ 'සංවරණය හා තුලනය' (Checks and Balances) පවත්වාගැනීමට පාර්ලිමේන්තුවට පවරා ඇති ප්‍රධාන මෙවලම් මොනවාද?", "වාචික ප්‍රශ්න ඇසීම, කාරක සභා පරීක්ෂණ (COPE/COPA), අයවැය විවාදය හා විශ්වාසභංග යෝජනා", "විනිසුරුවරුන්ට පහර දීම", "මැතිවරණ පෝරම ඉරා දැමීම", "රාජ්‍ය රහස් විකිණීම", "විධායකයේ ක්‍රියාකාරිත්වය නිරන්තරයෙන් ප්‍රශ්න කිරීමට ව්‍යවස්ථාදායකයට ඇති බලය දූෂණය පාලනය කරයි."),
    q("ශ්‍රී ලංකාවේ 'අධිකරණ සේවා කොමිෂන් සභාව' ස්වාධීනව ක්‍රියා කිරීමෙන් යහපාලනයට සිදුවන යහපත කුමක්ද?", "මහේස්ත්‍රාත්වරුන් හා දිසා විනිසුරුවරුන් දේශපාලන ඇඟිලි ගැසීම්වලින් තොරව පත් කර විනය පවත්වාගැනීම", "ඇමතිවරුන්ට නඩු තීන්දු ලිවීමට ඉඩ දීම", "විනිසුරුවරුන්ට මැතිවරණ ප්‍රචාරණයට ඉඩ දීම", "අධිකරණ වසා දැමීම", "අධිකරණ ස්වාධීනත්වය පුරවැසියන්ට අපක්ෂපාතී යුක්තිය ලැබීමට ඇති ප්‍රධානතම සහතිකයයි."),
    q("ගැටුමකදී 'සහජීවනය' (Co-existence) ගොඩනැගීම සඳහා පුද්ගලයන් අතර වගා කළ යුතු ප්‍රධාන මානුෂීය ගුණාංග මොනවාද?", "සහකම්පනය, ඉවසීම, සමාව දීම සහ අන්‍යෝන්‍ය විශ්වාසය", "පළිගැනීම, කෝපය සහ සැකය", "ආත්මාර්ථකාමී බව සහ උඩඟුකම", "අනෙකාගේ වේදනාවට සිනාසීම", "එකම රටක විවිධ ප්‍රජාවන් සතුටින් හා ආරක්ෂිතව ජීවත් වීමට මෙම සමාජ ගුණාංග අත්‍යවශ්‍යය."),
    q("තොරතුරු දැනගැනීමේ පනතේ සඳහන් 'රාජ්‍ය ආරක්ෂාවට බරපතළ හානියක් වන තොරතුරු' හෙළි නොකිරීමේදී පවා සලකා බලන විශේෂ නීතිය කුමක්ද?", "මහජන යහපත ප්‍රමුඛ වීමේ පරීක්ෂණය (Public Interest Override - Section 5(4))", "සියලු තොරතුරු සදහටම වසා දැමීමේ නීතිය", "පොලිස් ආඥාපනත පමණි", "රේගු බදු පනත පමණි", "තොරතුර හෙළි කිරීමෙන් ලැබෙන මහජන යහපත, ව්‍යතිරේකයෙන් රැකෙන හානියට වඩා විශාල නම් තොරතුර දිය යුතුය."),
    q("ශ්‍රී ලංකාවේ 2015 දී පිහිටුවූ 19 වන සංශෝධනයෙන් පසු 2022 දී සම්මත කළ කුමන සංශෝධනයෙන් යළිත් ස්වාධීන කොමිෂන් සභා ශක්තිමත් කළේද?", "21 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය", "12 වන සංශෝධනය", "16 වන සංශෝධනය", "18 වන සංශෝධනය", "2022 ඔක්තෝබර් 21 වන සංශෝධනය මඟින් ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව හා ස්වාධීන කොමිෂන් සභා යළි ස්ථාපිත කෙරිණි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පුරවැසියෙකු යහපාලනය වෙනුවෙන් ඉටු කරන 'ප්‍රායෝගික දායකත්වයක්' වන්නේ කුමක්ද?", "නීතිගරුක වීම, අල්ලස් නොදී සේවා ඉල්ලීම, බදු ගෙවීම හා RTI මඟින් ප්‍රශ්න කිරීම", "පොදු දේපළ කැඩීම", "අල්ලස් දී රියදුරු බලපත්‍ර ගැනීම", "ඡන්දය ප්‍රකාශ නොකර මගහැරීම", "පාලකයන් පමණක් නොව පුරවැසියන්ද අල්ලස ප්‍රතික්ෂේප කළ විට යහපාලනය යථාර්ථයක් වේ.")
  )
}

